"""Grammar theory for the 12 grammar units of Destination C1 (explanations in Spanish, examples in English)."""

def S(title, explain, examples, tip=None):
    d = {"title": title, "explain": explain, "examples": examples}
    if tip:
        d["tip"] = tip
    return d

